 public static partial class ThemeKitBuilder {
  static void ETaperedPylon(Transform parent,Vector3 position){float b=3.3f*.7071f,u=2.65f*.7071f,bd=b*.72f,ud=u*.72f;var vertices=new List<Vector3>{new Vector3(-b,0,-bd),new Vector3(b,0,-bd),new Vector3(b,0,bd),new Vector3(-b,0,bd),new Vector3(-u,8,-ud),new Vector3(u,8,-ud),new Vector3(u,8,ud),new Vector3(-u,8,ud)};var triangles=new List<int>{0,4,1,1,4,5,1,5,2,2,5,6,2,6,3,3,6,7,3,7,0,0,7,4,4,7,5,5,7,6,0,1,3,1,2,3};var g=MeshObject(parent,"Rectangular Tapered Pylon",vertices,triangles,sand);g.transform.localPosition=position;}
  static void EStonePyramid(Transform t,float width,float height,int kind){
   var tones=new Material[6];for(int i=0;i<tones.Length;i++)tones[i]=Paint("Desert Baked Pyramid Stone "+i,new Color(.82f,.65f,.41f)*( .94f+i*.025f),.22f);
   var mortar=Paint("Desert Baked Pyramid Mortar",new Color(.77f,.60f,.37f),.22f);var vertices=new List<Vector3>[7];var triangles=new List<int>[7];for(int i=0;i<7;i++){vertices[i]=new List<Vector3>();triangles[i]=new List<int>();}
   int rows=Mathf.CeilToInt(height/.72f);var random=new System.Random((int)(width*73+height*19)+kind*97);
   Func<float,float> radius=y=>{float u=y/height;return kind==1?(u<.58f?Mathf.Lerp(width*.5f,width*.23f,u/.58f):Mathf.Lerp(width*.23f,0,(u-.58f)/.42f)):width*.5f*(1-u);};
   for(int face=0;face<4;face++){var rotation=Quaternion.Euler(0,face*90,0);var normal=rotation*Vector3.back;
    for(int row=0;row<rows;row++){float y0=height*row/rows,y1=height*(row+1)/rows,r0=radius(y0),r1=radius(y1);int columns=Mathf.Max(1,Mathf.RoundToInt(r0*2/1.8f));
     for(int c=0;c<columns;c++){var corners=new[]{new Vector3(Mathf.Lerp(-r0,r0,(float)c/columns),y0,-r0),new Vector3(Mathf.Lerp(-r0,r0,(float)(c+1)/columns),y0,-r0),new Vector3(Mathf.Lerp(-r1,r1,(float)(c+1)/columns),y1,-r1),new Vector3(Mathf.Lerp(-r1,r1,(float)c/columns),y1,-r1)};var center=(corners[0]+corners[1]+corners[2]+corners[3])*.25f;var inner=new Vector3[4];for(int k=0;k<4;k++){inner[k]=rotation*(center+(corners[k]-center)*.965f);corners[k]=rotation*corners[k];}
      int tone=random.Next(6);EStoneQuad(vertices[tone],triangles[tone],inner[0],inner[1],inner[2],inner[3],normal);
      for(int k=0;k<4;k++){int n=(k+1)%4;EStoneQuad(vertices[6],triangles[6],corners[k],corners[n],inner[n],inner[k],normal);}
     }
    }
   }
   for(int i=0;i<7;i++)MeshObject(t,i==6?"Tessellated Mortar Strips":"Stable Stone Face Tiles "+i,vertices[i],triangles[i],i==6?mortar:tones[i]);
   Box(t,"Grounded Pyramid Foundation",new Vector3(0,.08f,0),new Vector3(width+.3f,.16f,width+.3f),eClay);
   // The entry is placed outside the sloped face, never coplanar with its stone tiles.
   float z=-radius(.8f)-.09f;MeshObject(t,"Pyramid Entry Shadow",new List<Vector3>{new Vector3(-.65f,.16f,-radius(.16f)-.08f),new Vector3(-.65f,1.6f,-radius(1.6f)-.08f),new Vector3(.65f,1.6f,-radius(1.6f)-.08f),new Vector3(.65f,.16f,-radius(.16f)-.08f)},new List<int>{0,1,2,0,2,3},eDark);
   foreach(float side in new[]{-1f,1f})Beam(t,"Sloped Entry Jamb",new Vector3(side*.8f,.15f,-radius(.15f)-.1f),new Vector3(side*.8f,1.72f,-radius(1.72f)-.1f),.26f,eLight);
   Box(t,"Pyramid Passage Lintel",new Vector3(0,1.7f,-radius(1.7f)-.12f),new Vector3(1.85f,.24f,.4f),eLight);
  }
  static void EStoneQuad(List<Vector3> vertices,List<int> triangles,Vector3 a,Vector3 b,Vector3 c,Vector3 d,Vector3 outward){EStoneTriangle(vertices,triangles,a,b,c,outward);EStoneTriangle(vertices,triangles,a,c,d,outward);}
  static void EStoneTriangle(List<Vector3> vertices,List<int> triangles,Vector3 a,Vector3 b,Vector3 c,Vector3 outward){var n=Vector3.Cross(b-a,c-a);if(n.sqrMagnitude<.00000001f)return;int k=vertices.Count;vertices.Add(a);if(Vector3.Dot(n,outward)<0){vertices.Add(c);vertices.Add(b);}else{vertices.Add(b);vertices.Add(c);}triangles.AddRange(new[]{k,k+1,k+2});}
  static void BuildEgyptStreetDetails(LoopThemeDefinition d){
   var props=new List<GameObject>(d.props.Where(p=>p&&!p.name.StartsWith("Desert Art ")));
   var obelisk=DesertModel("Hieroglyph Obelisk",t=>Obelisk(t,7));props.RemoveAll(p=>p.name=="Hieroglyph Obelisk");props.Add(obelisk);
   props.Add(DesertModel("Desert Art Rope and Bucket Well",t=>{RStoneRing(t,"Well Hollow Curb",0,1,.25f,.85f,eLight);EClosedCylinder(t,"Deep Well Interior",new Vector3(0,.2f,0),.74f,.025f,eDark,16);foreach(float x in new[]{-1.05f,1.05f})Beam(t,"Well Grounded Upright",new Vector3(x,0,0),new Vector3(x,2.85f,0),.16f,eWood);Beam(t,"Well Axle",new Vector3(-1.2f,2.25f,0),new Vector3(1.2f,2.25f,0),.17f,eWood);Box(t,"Well Supported Shade Roof",new Vector3(0,2.82f,0),new Vector3(2.8f,.14f,1.8f),eCloth);EClosedCylinder(t,"Suspended Water Bucket",new Vector3(0,.72f,0),.24f,.35f,eWood,12);Arc(t,"Bucket Handle",new Vector3(0,1.07f,0),.24f,.04f,.05f,eWood,10);Beam(t,"Bucket Rope",new Vector3(0,2.25f,0),new Vector3(0,1.31f,0),.035f,eRope);Beam(t,"Winch Handle",new Vector3(1.18f,2.25f,0),new Vector3(1.18f,2.0f,-.3f),.075f,eWood);}));
   props.Add(DesertModel("Desert Art Fruit and Date Counter",t=>EProduce(t,Vector3.zero)));
   props.Add(DesertModel("Desert Art Caravan Water Cart",t=>{Box(t,"Cart Supported Bed",new Vector3(0,.95f,0),new Vector3(2.8f,.18f,1.45f),eWood);Beam(t,"Cart Axle",new Vector3(-.4f,.6f,-.95f),new Vector3(-.4f,.6f,.95f),.13f,eWood);foreach(float side in new[]{-1f,1f}){Beam(t,"Cart Axle Bracket",new Vector3(-.4f,.6f,side*.55f),new Vector3(-.4f,.95f,side*.55f),.15f,eWood);var wheel=new GameObject("Closed Wagon Wheel");wheel.transform.SetParent(t,false);wheel.transform.localPosition=new Vector3(-.4f,.6f,side*.82f-.08f);wheel.transform.localRotation=Quaternion.Euler(90,0,0);EClosedCylinder(wheel.transform,"Solid Cart Wheel",Vector3.zero,.6f,.16f,eWood,14);EClosedCylinder(wheel.transform,"Wheel Hub",new Vector3(0,-.03f,0),.15f,.22f,eLight,10);Beam(t,"Cart Pull Shaft",new Vector3(1.2f,.95f,side*.5f),new Vector3(2.8f,.3f,side*.45f),.11f,eWood);}for(int i=0;i<3;i++){var jar=new GameObject("Secured Water Jar");jar.transform.SetParent(t,false);jar.transform.localPosition=new Vector3(-.8f+i*.8f,1.04f,0);Urn(jar.transform,eClay,.6f);}}));
   props.Add(DesertModel("Desert Art Date Basket Stack",t=>{for(int i=0;i<3;i++){Vector3 p=new Vector3((i-1)*.7f,0,(i%2)*.35f);Lathe(t,"Woven Date Basket",p,new[]{0f,.15f,.65f},new[]{.27f,.43f,.45f},eCloth,10);for(int j=0;j<4;j++)Ball(t,"Basket Dates",p+new Vector3((j%2)*.27f-.13f,.68f,(j/2)*.27f-.13f),new Vector3(.28f,.18f,.25f),eFruit);}}));
   props.Add(DesertModel("Desert Art Market Crates",t=>{for(int crate=0;crate<2;crate++){Vector3 p=new Vector3(crate*.95f,crate*.25f,0);foreach(float x in new[]{-.38f,.38f})foreach(float z in new[]{-.35f,.35f})Box(t,"Crate Corner Post",p+new Vector3(x,.45f,z),new Vector3(.08f,.9f,.08f),eWood);for(int row=0;row<3;row++)foreach(float z in new[]{-.35f,.35f})Box(t,"Crate Side Slat",p+new Vector3(0,.16f+row*.28f,z),new Vector3(.85f,.18f,.07f),eWood);Box(t,"Crate Bottom",p+new Vector3(0,.04f,0),new Vector3(.85f,.08f,.8f),eWood);}Box(t,"Stack Support Under Raised Crate",new Vector3(.95f,.125f,0),new Vector3(.85f,.25f,.8f),eWood);}));
   props.Add(DesertModel("Desert Art Clay Water Jar",t=>{Urn(t,eClay);Beam(t,"Water Jar Stopper Cord",new Vector3(-.18f,1.47f,0),new Vector3(.18f,1.47f,0),.04f,eRope);Cylinder(t,"Water Jar Woven Stopper",new Vector3(0,1.46f,0),.27f,.10f,eCloth,12);}));
   props.Add(DesertModel("Desert Art Woven Rug Rack",t=>{foreach(float x in new[]{-1.2f,1.2f})Beam(t,"Rug Rack Ground Post",new Vector3(x,0,0),new Vector3(x,2.3f,0),.12f,eWood);Beam(t,"Rug Hanging Crossbar",new Vector3(-1.4f,2.25f,0),new Vector3(1.4f,2.25f,0),.12f,eWood);for(int i=0;i<3;i++){float x=(i-1)*.8f;Box(t,"Hanging Carpet",new Vector3(x,1.5f,-.03f),new Vector3(.7f,1.5f,.08f),i%2==0?eRed:eBlue);for(int stripe=0;stripe<4;stripe++)Box(t,"Woven Carpet Stripe",new Vector3(x,1.0f+stripe*.3f,-.08f),new Vector3(.7f,.06f,.035f),eCloth);}}));
   d.props=props.ToArray();var plants=new List<GameObject>(d.vegetation.Where(p=>p&&!p.name.StartsWith("Desert Art ")));
   plants.Add(DesertModel("Desert Art Dry Grass Tufts",t=>{for(int i=0;i<13;i++){float a=i*2.399f,x=Mathf.Sin(a)*.65f,z=Mathf.Cos(a)*.4f,h=.55f+(i%4)*.16f;Beam(t,"Grounded Dry Grass Blade",new Vector3(x,0,z),new Vector3(x+Mathf.Sin(a)*.28f,h,z+Mathf.Cos(a)*.22f),.035f,eGrass);}}));
   plants.Add(DesertModel("Desert Art Thorn Scrub",t=>{for(int i=0;i<7;i++){float a=i*2.399f;Vector3 p=new Vector3(Mathf.Sin(a)*.65f,.45f,Mathf.Cos(a)*.4f);Beam(t,"Scrub Ground Branch",new Vector3(0,0,0),p,.055f,eWood);Ball(t,"Dry Scrub Crown",p,new Vector3(.7f,.65f,.6f),eGrass);}}));
   plants.Add(DesertModel("Desert Art Small Acacia",t=>{Tube(t,"Acacia Connected Trunk",new List<Vector3>{Vector3.zero,new Vector3(.15f,1.3f,0),new Vector3(-.1f,2.5f,0)},.16f,eWood,9,.1f);for(int i=0;i<4;i++){float a=i*2.4f;Vector3 p=new Vector3(Mathf.Sin(a)*1.0f,2.9f+Mathf.Cos(a)*.16f,Mathf.Cos(a)*.8f);Beam(t,"Acacia Crown Branch",new Vector3(0,1.8f,0),p,.085f,eWood);Ball(t,"Muted Acacia Canopy",p,new Vector3(2,.7f,1.7f),eGrass);}}));d.vegetation=plants.ToArray();
  }
  static GameObject DesertHorizon(GameObject source,string name){var root=UnityEngine.Object.Instantiate(source);root.name=name;if(PrefabUtility.IsPartOfPrefabInstance(root))PrefabUtility.UnpackPrefabInstance(root,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var replacements=new Dictionary<Material,Material>();foreach(var renderer in root.GetComponentsInChildren<Renderer>()){var mats=renderer.sharedMaterials;for(int i=0;i<mats.Length;i++){var mat=mats[i];if(!replacements.ContainsKey(mat)){var c=mat.HasProperty("_Color")?mat.GetColor("_Color"):Color.white;replacements[mat]=Paint("Desert Horizon "+mat.name,Color.Lerp(c,new Color(.94f,.75f,.47f),.48f),.82f);}mats[i]=replacements[mat];}renderer.sharedMaterials=mats;}var prefab=PrefabUtility.SaveAsPrefabAsset(root,themeFolder+"/Models/"+name+".prefab");UnityEngine.Object.DestroyImmediate(root);return prefab;}
  static void BuildEgyptHorizon(LoopThemeDefinition d){
   var horizon=new List<GameObject>();foreach(var pair in new[]{new[]{"Desert Pyramid","Distant Great Pyramid"},new[]{"Desert Art Stepped Pyramid","Desert Horizon Stepped Pyramid"},new[]{"Desert Art Bent Pyramid","Desert Horizon Bent Pyramid"},new[]{"Desert Art Twin Royal Pyramids","Desert Horizon Twin Royal Pyramids"}}){var source=d.landmarks.First(p=>p.name==pair[0]);horizon.Add(DesertHorizon(source,pair[1]));}
   var statues=DesertModel("Desert Horizon Royal Statue Procession",t=>{for(int i=0;i<3;i++){var root=new GameObject("Guardian Statue "+i);root.transform.SetParent(t,false);root.transform.localPosition=new Vector3((i-1)*5,0,i%2);ERoyalStatue(root.transform,i%2==0);}});horizon.Add(DesertHorizon(statues,statues.name));
   horizon.Add(DesertModel("Desert Horizon Palace City",t=>{for(int i=0;i<5;i++){float h=3+(i%3)*1.3f;Box(t,"Remote Adobe Palace Mass",new Vector3((i-2)*3.4f,h*.5f,i%2),new Vector3(3.8f,h,4),eLight);Box(t,"Remote Roof Parapet",new Vector3((i-2)*3.4f,h+.15f,i%2),new Vector3(4.0f,.3f,4.2f),eClay);for(int j=0;j<2;j++)Box(t,"Remote Small Window",new Vector3((i-2)*3.4f+(j-.5f)*1.2f,2,-2+(i%2)-.03f),new Vector3(.5f,.7f,.06f),eClay);}}));
   horizon.Add(DesertModel("Desert Horizon Wind Dune Ridge",t=>{var v=new List<Vector3>();var tr=new List<int>();for(int i=0;i<=12;i++){float x=-20+i*40f/12,h=1.2f+Mathf.Sin(i*.45f)*1.2f;v.Add(new Vector3(x,0,-8));v.Add(new Vector3(x,h,0));v.Add(new Vector3(x,0,8));if(i<12){int k=i*3;tr.AddRange(new[]{k,k+1,k+3,k+1,k+4,k+3,k+1,k+2,k+4,k+2,k+5,k+4});}}MeshObject(t,"Connected Dune Surface",v,tr,eLight);}));d.background=horizon.ToArray();
  }
 }
